import{z as A,x as p,o,c as B,q as n,j as E,D as l,d as t,s as r,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"仅回复损失","description":"","frontmatter":{"title":"仅回复损失","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/response-only-loss.md","filePath":"llm/response-only-loss.md","lastUpdated":1791063341000}'),d={name:"llm/response-only-loss.md"};function m(c,a,h,u,D,f){const s=p("Mermaid");return o(),B("div",null,[a[2]||(a[2]=n('<h1 id="仅回复损失" tabindex="-1">仅回复损失 <a class="header-anchor" href="#仅回复损失" aria-label="Permalink to &quot;仅回复损失&quot;">​</a></h1><div class="epigraph"><p>用户段是条件，助手段才是被监督的完成；把提示也送进交叉熵，模型会学着把问题再写一遍，而不是学着回答。</p><footer>—— 与 Ouyang 等 InstructGPT（NeurIPS 2022）、Touvron 等 Llama 2（2023）的 SFT 实践一致：损失落在示范完成上</footer></div><p><a href="/llm/instruction-data-lineage">上一课</a>分清了 FLAN / Alpaca / ShareGPT 三条表。表一旦经<a href="/llm/chat-template">chat template</a>渲染，下一个缺口是：<strong>哪些 token 进梯度</strong>。预训练对整段因果语言建模；SFT 若原样照搬，用户问题、系统约束、工具结果都会被当成「下一词」。仅回复损失（response-only / completion-only）把交叉熵限制在助手完成上，提示只作条件。本课写掩码契约，不改谱系，也不谈<a href="/llm/sft-packing-mask">打包</a>如何把多条样本塞进同一序列。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一条渲染后的样本形如 \\(\\texttt{prefix}\\circ\\texttt{response}\\)。完整因果损失是</p> \\[\\mathcal{L}=\\sum_{t\\in T}-\\log p_\\theta(x_t\\mid x_{\\lt t}), \\]<p>若 \\(T\\) 含前缀，梯度鼓励模型在「用户刚问完」的位置上复述用户、或把系统提示续成更长的系统提示。评测时前缀由产品写入、不可改，训练时却在预测它，训练–推理目标不一致。多轮更严重：上一轮助手已在上下文里，若再对用户轮计损失，模型学会用用户口吻说话。</p><p>FLAN 短输入上，漏掩码表现为背题面；ShareGPT 长多轮上，漏掩码表现为角色崩溃。两种看起来像「微调毁了模型」，根因是 \\(T\\) 选错，不是<a href="/llm/full-sft-hparams">学习率</a>选错。<span class="marginnote">直觉类比：全序列损失像给阅卷老师定规矩——学生把题目一字不差抄一遍也给分。学生很快发现抄题比解题容易拿分，于是学会复述问题而不是回答问题。仅回复损失就是把「抄题」从评分表里删掉：题干摆在那里可以看（作条件），但只有写答案的位置才算分。</span></p><h3 id="掩码是模板的对偶" tabindex="-1">掩码是模板的对偶 <a class="header-anchor" href="#掩码是模板的对偶" aria-label="Permalink to &quot;掩码是模板的对偶&quot;">​</a></h3><p>模板负责标出角色边界，掩码负责决定边界内谁被学习。只改模板不改掩码，用户段仍进损失；只改掩码不改模板，角色在输入里看不见，掩码成了随机开关。<a href="/llm/instruction-data-lineage">上一课</a>的三条谱系对应不同的「回复」定义：FLAN 的输出字段、Alpaca 的 <code>Response</code>、对话里所有 <code>assistant</code> 轮（有时含工具参数）。必须按谱系定义 \\(T\\)，不能写死「最后一个段落」。</p><p><span class="marginnote">部分实现提供 <code>train_on_inputs=False</code>（如早期 Alpaca-LoRA 脚本）。默认若为 True，等于关闭本课。核对方法是打印 <code>labels</code>：前缀应为 ignore_index，助手段才是 token id。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>渲染整段对话，构造与 <code>input_ids</code> 等长的 <code>labels</code>：对系统、用户、（通常）工具结果位置写入忽略下标（PyTorch 惯例 \\(-100\\)），对应对齐的助手 token 写入真实 id。损失对忽略下标跳过。<span class="marginnote">数字实例：一条渲染后 1024 个 token 的样本，系统加用户加工具观察占 800，助手回复占 224。构造 labels 时前 800 位全填 \\(-100\\)，只有 224 位是真实 token id，交叉熵就只在这 224 个位置上求平均——有效监督量不是 1024 而是 224，按整段长度估计学习率或损失量级都会失真。</span>多轮则每一轮助手都进 \\(T\\)，不只最后一轮——否则模型只学「如何收尾」，不学中间轮。</p><p>工具调用若希望模型发出函数名与参数，这些 token 算回复，应进损失；工具返回的观察是下一轮条件，通常掩码。与<a href="/llm/chat-template">模板</a>的 <code>add_generation_prompt</code> 对齐：训练时完整助手正文在损失里，推理时生成从助手起始标记之后开始。</p>',14)),(o(),E(i,null,{default:l(()=>[r(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20R%5B%22chat%20template%20%E6%B8%B2%E6%9F%93%22%5D%20--%3E%20I%5B%22input_ids%20%E5%85%A8%E5%BA%8F%E5%88%97%22%5D%0A%20%20R%20--%3E%20L%5B%22labels%EF%BC%9A%E4%BB%85%E5%8A%A9%E6%89%8B%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20I%20--%3E%20M%5B%22%E5%9B%A0%E6%9E%9C%20LM%22%5D%0A%20%20L%20--%3E%20M%0A%20%20M%20--%3E%20G%5B%22%E6%A2%AF%E5%BA%A6%E5%8F%AA%E6%9D%A5%E8%87%AA%E5%9B%9E%E5%A4%8D%20token%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"特殊情况要写进配方。续写式任务（补全代码、填空）的「提示」本身是未完成文本，损失应从补全起点算，而不是从角色标记算。FLAN 分类任务若把标签词当回复，只对标签位置计损失即可，不必对解释性废话计损失——除非你确实想学那种废话。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"忽略前缀不改变注意力：前缀 token 仍作为键与值，回复位置仍能看见它们。改变的是参数更新的来源。设回复段梯度为 \\(\\nabla_\\theta \\mathcal{L}_{\\mathrm{resp}}\\)，前缀段若也计损失，会多一项 \\(\\nabla_\\theta \\mathcal{L}_{\\mathrm{pref}}\\)。后者沿残差刷到嵌入与底层，驱动模型把高频用户 n-gram 写进先验。SFT 数据远小于预训练，这项很容易压过「如何回答」的信号。",-1)),a[6]||(a[6]=e("p",null,[t("仅回复还有信噪比含义。前缀往往更长，尤其是 ShareGPT 与检索增强。全序列平均损失会被前缀主导，看起来很低（前缀好预测），回复质量却没动。"),e("span",{class:"marginnote"},"常见误区：盯着训练日志里 loss 从 1.2 降到 0.6 就认为微调在起效。若掩码没关紧，这 0.6 的大部分贡献可能来自「预测用户问题和系统提示」——这类文本高频、好猜，下降快；而真正关心的回复质量几乎没动。正确的报表只看回复段的负对数似然。"),t("报表应打回复段负对数似然，而不是整段 loss。这与预训练「整段都是目标」的日志习惯必须切开。")],-1)),(o(),E(i,null,{default:l(()=>[r(s,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E6%B8%B2%E6%9F%93%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20A%5B%22%E5%85%A8%E5%BA%8F%E5%88%97%E8%BF%9B%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20S%20--%3E%20B%5B%22%E4%BB%85%E5%9B%9E%E5%A4%8D%E8%BF%9B%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E5%89%8D%E7%BC%80%E6%A2%AF%E5%BA%A6%E5%88%B7%E5%B5%8C%E5%85%A5%E4%B8%8E%E5%BA%95%E5%B1%82%22%5D%0A%20%20A1%20--%3E%20A2%5B%22%E6%A8%A1%E5%9E%8B%E5%AD%A6%E4%BC%9A%E5%A4%8D%E8%BF%B0%E7%94%A8%E6%88%B7%E4%B8%8E%E7%B3%BB%E7%BB%9F%E6%8F%90%E7%A4%BA%22%5D%0A%20%20A2%20--%3E%20A3%5B%22%E8%A7%92%E8%89%B2%E5%B4%A9%E6%BA%83%20%E6%95%B4%E6%AE%B5%20loss%20%E5%8D%B4%E5%BE%88%E4%BD%8E%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E5%89%8D%E7%BC%80%E5%8F%AA%E4%BD%9C%E9%94%AE%E5%80%BC%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E6%A2%AF%E5%BA%A6%E5%85%A8%E9%83%A8%E6%9D%A5%E8%87%AA%E5%9B%9E%E5%A4%8D%20token%22%5D%0A%20%20B2%20--%3E%20B3%5B%22%E5%AD%A6%E4%BC%9A%E5%9B%9E%E7%AD%94%20%E8%A7%92%E8%89%B2%E7%A8%B3%E5%AE%9A%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">仅回复不是「不学上下文」。上下文通过条件进入 \\(p(\\text{response}\\mid\\text{prefix})\\)。它禁止的是把条件本身当生成目标。若任务真是续写用户草稿，应把草稿标成助手段，而不是关掉掩码。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不是所有后训练都仅回复。继续预训练、领域自适应的第一阶段（见后课<a href="/llm/domain-adaptation-ft">领域适配</a>）常对全文计损失。偏好方法（DPO 等）在完成上比较，前缀同样是条件。本课只约束监督 SFT。</p><p>掩码过窄也会出事：若系统里有必须学会的固定拒答句，却全部掩码，模型只能从稀少助手示范里学拒绝。那时应把该句挪到助手示范，而不是把整个系统段解掩码。全参与 <a href="/llm/lora">LoRA</a> 用同一套 labels；LoRA 不减免掩码错误，只让错误更新进适配器。</p><p>调试顺序：先对训练/推理<a href="/llm/chat-template">模板</a>，再打印 <code>labels</code> 热图，最后才动 \\(\\eta\\)。角色崩溃优先当掩码 bug。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SFT 的交叉熵应落在助手完成上；前缀只作因果条件。</li><li><code>labels</code> 与 chat template 是对偶：模板标角色，掩码选梯度。</li><li>多轮应对每一轮助手计损失；工具观察通常掩码，工具调用通常不掩码。</li><li>报表看回复段 NLL；整段 loss 会被长前缀粉饰。</li><li>漏掩码表现为复述用户或角色崩溃，常被误诊为学习率或遗忘。</li><li>出处：与 InstructGPT、Llama 2 的 SFT 目标一致；实现契约见各框架的 completion-only / <code>train_on_inputs=False</code>。</li></ul>',7))])}const F=A(d,[["render",m]]);export{T as __pageData,F as default};
